func hook_power(views: SimViews, scope: WriteScope, ctx: HookContext) -> CompletionToken:

static func run(s: GraphState, c: GraphCaches, x: GraphScratch, d: GraphDiag, t: GraphTuning, scope: WriteScope, w: WorkCounter) -> void:
	var links: PackedInt32Array = c.exchange_links               # derived list: stored OPENINGs, hull holes, seam weeps (members read through the object each call, ADR-0011 § 6.2)
	for k in c.exchange_link_count:
		var e: int = links[k]
		var ra: int = c.edge_a_comp_row[e]
		var rb: int = c.edge_b_comp_row[e]
		var g: int = s._c_n_total_at(ra) * c.comp_v[rb] - s._c_n_total_at(rb) * c.comp_v[ra]   # exact integer gradient of start-of-phase amounts
		if g == 0:
			continue
		var dn: int = GraphRules.gas_flux(absi(g), c.comp_v[ra], c.comp_v[rb], c.edge_area_m[e], x.deg_max_of(e), t.g_open, t.gas_scale)
		# direction from the sign of g; species split Δn_o2 = floor_div(dn * n_o2_src, n_tot_src); remainder inert; accumulate, never write n_* here
		x.add_flux(ra, rb, g > 0, dn, s)
	w.add(WorkCounter.UNIT_EDGE, c.exchange_link_count)

